def smallestWithinBudget(s, k):
    out = list(s)
    for i, ch in enumerate(s):
        c = ord(ch) - 97
        d = min(c, 26 - c)
        if d <= k:
            out[i] = 'a'
            k -= d
        else:
            out[i] = chr(ord(ch) - k)
            k = 0
            break
    return ''.join(out)
